package pe.upeu.ecorecicla;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.*;
import org.springframework.test.context.ActiveProfiles;
import java.time.LocalDate;
import java.time.Instant;
import java.util.*;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.io.Decoders;
import io.jsonwebtoken.security.Keys;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
@ActiveProfiles("test")
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class ApiIntegracionTest {
 @Autowired TestRestTemplate http; @Autowired ObjectMapper json; @Autowired JdbcTemplate jdbc;
 private String token(String usuario){var r=http.postForEntity("/api/v1/auth/login",Map.of("usuario",usuario,"contrasena","Eco2026*"),String.class);assertEquals(200,r.getStatusCode().value(),r.getBody());try{return json.readTree(r.getBody()).get("token").asText();}catch(Exception e){throw new RuntimeException(e);}}
 private HttpHeaders headers(String token){HttpHeaders h=new HttpHeaders();h.setBearerAuth(token);h.setContentType(MediaType.APPLICATION_JSON);return h;}
 private JsonNode body(ResponseEntity<String> r){try{return json.readTree(r.getBody());}catch(Exception e){throw new RuntimeException(e);}}
 @Test @Order(1) void autenticaYDevuelveIdentidadYPrivilegios(){String t=token("operario1");var r=http.exchange("/api/v1/usuarios/actual",HttpMethod.GET,new HttpEntity<>(headers(t)),String.class);assertEquals(200,r.getStatusCode().value());assertEquals("operario1",body(r).get("usuario").asText());assertTrue(body(r).get("privilegios").toString().contains("PESAJE_CREAR"));}
 @Test @Order(2) void credencialesIncorrectasDan401(){var r=http.postForEntity("/api/v1/auth/login",Map.of("usuario","operario1","contrasena","incorrecta"),String.class);assertEquals(401,r.getStatusCode().value());assertEquals(401,body(r).get("status").asInt());}
 @Test @Order(3) void tokenAusenteManipuladoYVencidoDan401(){var no=http.getForEntity("/api/v1/puntos",String.class);assertEquals(401,no.getStatusCode().value());HttpHeaders h=headers(token("operario1").concat("x"));var bad=http.exchange("/api/v1/puntos",HttpMethod.GET,new HttpEntity<>(h),String.class);assertEquals(401,bad.getStatusCode().value());String clave="MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=";String vencido=Jwts.builder().subject("operario1").claim("uid",1).claim("privilegios",List.of("PUNTO_LEER")).issuedAt(Date.from(Instant.now().minusSeconds(7200))).expiration(Date.from(Instant.now().minusSeconds(3600))).signWith(Keys.hmacShaKeyFor(Decoders.BASE64.decode(clave))).compact();var expired=http.exchange("/api/v1/puntos",HttpMethod.GET,new HttpEntity<>(headers(vencido)),String.class);assertEquals(401,expired.getStatusCode().value());}
 @Test @Order(4) void privilegioInsuficienteDa403(){var r=http.exchange("/api/v1/puntos",HttpMethod.POST,new HttpEntity<>(Map.of("razonSocial","No autorizado","direccion","Calle","zona","Centro","materialHabitual","PAPEL"),headers(token("operario1"))),String.class);assertEquals(403,r.getStatusCode().value());assertEquals("Forbidden",body(r).get("error").asText());}
 @Test @Order(5) void listaPuntosPaginadaYFiltrada(){var r=http.exchange("/api/v1/puntos?pagina=0&tamanio=2&zona=Centro",HttpMethod.GET,new HttpEntity<>(headers(token("operario1"))),String.class);assertEquals(200,r.getStatusCode().value());assertEquals(2,body(r).get("contenido").size());assertEquals(4,body(r).get("totalElementos").asInt());assertEquals(2,body(r).get("tamanio").asInt());}
 @Test @Order(6) void calculaNetoYRechazaPesajeInvalido(){String t=token("operario1");JsonNode route=body(http.exchange("/api/v1/rutas/asignada?fecha="+LocalDate.now(java.time.ZoneId.of("America/Lima")),HttpMethod.GET,new HttpEntity<>(headers(t)),String.class));long ruta=route.get("id").asLong(), punto=route.get("puntos").get(0).get("id").asLong();Map<String,Object> q=Map.of("pesoBruto",31.5,"tara",2.25,"material","PAPEL","observacion","prueba","pesoNeto",999);var made=http.exchange("/api/v1/rutas/"+ruta+"/puntos/"+punto+"/pesajes",HttpMethod.POST,new HttpEntity<>(q,headers(t)),String.class);assertEquals(201,made.getStatusCode().value());assertEquals(29.25,body(made).get("pesoNeto").asDouble());var invalid=http.exchange("/api/v1/rutas/"+ruta+"/puntos/"+punto+"/pesajes",HttpMethod.POST,new HttpEntity<>(Map.of("pesoBruto",2,"tara",2,"material","PAPEL"),headers(t)),String.class);assertEquals(400,invalid.getStatusCode().value());assertTrue(body(invalid).get("validationErrors").has("pesoBruto"));}
 @Test @Order(7) void operarioCorrigeSoloLoPropioYDelDia(){String op=token("operario1");JsonNode route=body(http.exchange("/api/v1/rutas/asignada?fecha="+LocalDate.now(java.time.ZoneId.of("America/Lima")),HttpMethod.GET,new HttpEntity<>(headers(op)),String.class));long id=-1;for(JsonNode p:route.get("puntos")){var page=http.exchange("/api/v1/puntos/"+p.get("id").asLong()+"/pesajes",HttpMethod.GET,new HttpEntity<>(headers(op)),String.class);for(JsonNode x:body(page).get("contenido"))if(x.get("operario").asText().equals("operario1")&&x.get("estado").asText().equals("REGISTRADO"))id=x.get("id").asLong();}assertTrue(id>0);var r=http.exchange("/api/v1/pesajes/"+id,HttpMethod.PUT,new HttpEntity<>(Map.of("pesoBruto",32,"tara",2,"material","PAPEL"),headers(op)),String.class);assertEquals(200,r.getStatusCode().value());jdbc.update("UPDATE pesajes SET fecha_hora = ? WHERE id = ?",java.sql.Timestamp.from(LocalDate.now(java.time.ZoneId.of("America/Lima")).minusDays(1).atStartOfDay(java.time.ZoneId.of("America/Lima")).toInstant()),id);var expired=http.exchange("/api/v1/pesajes/"+id,HttpMethod.PUT,new HttpEntity<>(Map.of("pesoBruto",32,"tara",2,"material","PAPEL"),headers(op)),String.class);assertEquals(403,expired.getStatusCode().value());}
 @Test @Order(8) void operarioNoCorrigePesajeAjeno(){String op=token("operario1");JsonNode route=body(http.exchange("/api/v1/rutas/asignada?fecha="+LocalDate.now(java.time.ZoneId.of("America/Lima")),HttpMethod.GET,new HttpEntity<>(headers(op)),String.class));long id=-1;for(JsonNode p:route.get("puntos")){var page=http.exchange("/api/v1/puntos/"+p.get("id").asLong()+"/pesajes",HttpMethod.GET,new HttpEntity<>(headers(op)),String.class);for(JsonNode x:body(page).get("contenido"))if(x.get("operario").asText().equals("operario2"))id=x.get("id").asLong();}assertTrue(id>0,"falta pesaje del segundo operario");var r=http.exchange("/api/v1/pesajes/"+id,HttpMethod.PUT,new HttpEntity<>(Map.of("pesoBruto",22,"tara",1,"material","PAPEL"),headers(op)),String.class);assertEquals(403,r.getStatusCode().value());}
 @Test @Order(9) void rutaDeAyerRechazaRegistroYCorreccion(){String op=token("operario1"),sup=token("supervisor1");JsonNode route=body(http.exchange("/api/v1/rutas/asignada?fecha="+LocalDate.now(java.time.ZoneId.of("America/Lima")).minusDays(1),HttpMethod.GET,new HttpEntity<>(headers(op)),String.class));long ruta=route.get("id").asLong(),punto=route.get("puntos").get(0).get("id").asLong();var create=http.exchange("/api/v1/rutas/"+ruta+"/puntos/"+punto+"/pesajes",HttpMethod.POST,new HttpEntity<>(Map.of("pesoBruto",30,"tara",2,"material","PAPEL"),headers(sup)),String.class);assertEquals(409,create.getStatusCode().value());var page=http.exchange("/api/v1/puntos/"+punto+"/pesajes",HttpMethod.GET,new HttpEntity<>(headers(op)),String.class);long pesaje=body(page).get("contenido").get(0).get("id").asLong();var edit=http.exchange("/api/v1/pesajes/"+pesaje,HttpMethod.PUT,new HttpEntity<>(Map.of("pesoBruto",30,"tara",2,"material","PAPEL"),headers(sup)),String.class);assertEquals(409,edit.getStatusCode().value());}
 @Test @Order(10) void anulacionEsLogicaYConservaLaFila(){String sup=token("supervisor1"),op=token("operario1");JsonNode route=body(http.exchange("/api/v1/rutas/asignada?fecha="+LocalDate.now(java.time.ZoneId.of("America/Lima")),HttpMethod.GET,new HttpEntity<>(headers(op)),String.class));long punto=route.get("puntos").get(0).get("id").asLong();var page=http.exchange("/api/v1/puntos/"+punto+"/pesajes",HttpMethod.GET,new HttpEntity<>(headers(op)),String.class);long id=body(page).get("contenido").get(0).get("id").asLong();var deleted=http.exchange("/api/v1/pesajes/"+id+"/anulacion",HttpMethod.POST,new HttpEntity<>(Map.of("motivo","Pesaje de prueba anulado"),headers(sup)),String.class);assertEquals(200,deleted.getStatusCode().value());assertEquals("ANULADO",body(deleted).get("estado").asText());var after=http.exchange("/api/v1/puntos/"+punto+"/pesajes",HttpMethod.GET,new HttpEntity<>(headers(op)),String.class);assertTrue(body(after).get("contenido").toString().contains("Pesaje de prueba anulado"));}
 @Test @Order(11) void rutaAbiertaRechazaCierreIncompletoYLuegoAceptaOmisiones(){String op=token("operario1"),sup=token("supervisor1");JsonNode route=body(http.exchange("/api/v1/rutas/asignada?fecha="+LocalDate.now(java.time.ZoneId.of("America/Lima")),HttpMethod.GET,new HttpEntity<>(headers(op)),String.class));long id=route.get("id").asLong();var conflict=http.exchange("/api/v1/rutas/"+id+"/cierre",HttpMethod.POST,new HttpEntity<>(headers(sup)),String.class);assertEquals(409,conflict.getStatusCode().value());assertTrue(body(conflict).get("message").asText().contains("faltan"));for(JsonNode p:route.get("puntos")){long punto=p.get("id").asLong();if(!p.get("atendido").asBoolean()){var omission=http.exchange("/api/v1/rutas/"+id+"/puntos/"+punto+"/omision",HttpMethod.POST,new HttpEntity<>(Map.of("motivo","Acceso no disponible"),headers(sup)),String.class);assertEquals(200,omission.getStatusCode().value());}}var closed=http.exchange("/api/v1/rutas/"+id+"/cierre",HttpMethod.POST,new HttpEntity<>(headers(sup)),String.class);assertEquals(200,closed.getStatusCode().value());assertEquals("CERRADA",body(closed).get("estado").asText());}
}
